package com.joseph.ad04.config;
import jakarta.persistence.EntityManager; import jakarta.persistence.EntityManagerFactory; import jakarta.persistence.Persistence;
public final class JPAUtil { private static final EntityManagerFactory EMF=Persistence.createEntityManagerFactory("activaPU"); private JPAUtil(){} public static EntityManager crearEntityManager(){return EMF.createEntityManager();} public static void cerrar(){if(EMF.isOpen())EMF.close();} }